static long compressTimeBucket(long timeBucket, int dayStep) {
    // Convert the timeBucket to a Calendar instance
    Calendar calendar = Calendar.getInstance();
    calendar.setTimeInMillis(timeBucket);

    // Get the year, month, and day from the calendar
    int year = calendar.get(Calendar.YEAR);
    int month = calendar.get(Calendar.MONTH) + 1; // Calendar.MONTH is zero-based
    int day = calendar.get(Calendar.DAY_OF_MONTH);

    // Calculate the day of the month relative to the start of the month
    int dayOfMonth = day - 1;

    // Calculate the new day based on the dayStep
    int newDay = (dayOfMonth / dayStep) * dayStep + 1;

    // Set the new day in the calendar
    calendar.set(Calendar.DAY_OF_MONTH, newDay);

    // Return the new time bucket as a long value
    return calendar.getTimeInMillis();
}

