public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    buffer.clear();

    // Read from the input stream into the buffer
    int bytesRead = in.read(buffer.array(), buffer.position(), buffer.remaining());

    // If no bytes were read, throw an IOException
    if (bytesRead == -1) {
        throw new IOException("End of stream reached before buffer could be filled");
    }

    // Set the limit to the number of bytes actually read
    buffer.limit(buffer.position() + bytesRead);

    // Reset the position to the start of the buffer
    buffer.position(0);
}

