public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1) {
        return 2;
    }

    int prime = desiredCapacity;
    boolean found = false;

    while (!found) {
        prime = nextCandidate(prime);
        if (isPrime(prime)) {
            found = true;
        }
    }

    return prime;
}

private static int nextCandidate(int current) {
    if (current <= 2) {
        return 2;
    }
    if (current % 2 == 0) {
        return current + 1;
    }
    return current + 2;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

