public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean escape = false;

    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (escape) {
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape character: \\" + c);
            }
            escape = false;
        } else if (c == '\\') {
            escape = true;
        } else {
            sb.append(c);
        }
    }

    if (escape) {
        throw new Exception("Unmatched escape character at the end of the string");
    }

    return sb.toString();
}

