public static String applyRelativePath(String path, String relativePath) {
    // Normalize the paths to ensure they use the correct separator
    path = path.replace(File.separatorChar, '/');
    relativePath = relativePath.replace(File.separatorChar, '/');

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");

    // Use a stack to handle the relative path components
    Stack<String> stack = new Stack<>();
    for (String component : pathComponents) {
        if (!component.isEmpty() && !component.equals(".")) {
            stack.push(component);
        }
    }

    for (String component : relativeComponents) {
        if (component.equals("..")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!component.isEmpty() && !component.equals(".")) {
            stack.push(component);
        }
    }

    // Reconstruct the full path
    StringBuilder fullPath = new StringBuilder();
    while (!stack.isEmpty()) {
        fullPath.insert(0, stack.pop());
        if (!stack.isEmpty()) {
            fullPath.insert(0, "/");
        }
    }

    return fullPath.toString();
}

